OC.AppConfig={url:OC.generateUrl("/settings/appconfig"),getValue:function(u,e,n,p){null==n?$.ajax({url:`${OC.AppConfig.url}/${u}/${e}`,success:p}):$.ajax({url:`${OC.AppConfig.url}/${u}/${e}?default=${n}`,success:p})},setValue:function(u,e,n){return $.ajax({url:OC.AppConfig.url,type:"PUT",data:{app:u,key:e,value:n}})},getApps:function(u){$.ajax({url:OC.AppConfig.url,success:u})},getKeys:function(u,e){$.ajax({url:`${OC.AppConfig.url}/${u}`,success:e})},hasKey:function(u,e,n){$.ajax({url:`${OC.AppConfig.url}/${u}/${e}`,success:function(u){n(null!==u)}})},deleteKey:function(u,e){$.ajax({url:`${OC.AppConfig.url}/${u}/${e}`,type:"DELETE"})},deleteApp:function(u){$.ajax({url:`${OC.AppConfig.url}/${u}`,type:"DELETE"})}};